import { Activity, ArrowDownLeft, ArrowLeftRight, ArrowUpRight, Barcode, Bell, Boxes, BriefcaseBusiness, CalendarDays, Camera, Check, ChevronDown, CircleDollarSign, Clock3, Cloud, CloudOff, Copy, CreditCard, Eye, EyeOff, FileBarChart, FileText, Headphones, Home, IndianRupee, KeyRound, Laptop, Menu, Moon, Package, Plus, Printer, Search, Settings, ShieldCheck, ShoppingBag, ShoppingCart, Smartphone, Sun, Truck, Users, Wallet, X, Zap } from 'lucide-react';
import { type DataState, type Product, type Customer, type Supplier, type Invoice, type Purchase, type Expense, type ReturnRecord, type Warranty, loadState, saveState, seed, uid } from './store';
